mapper.select:
select id, project_id, budget_category_id, amount, expense_date, vendor, invoice_no, receipt_file, description, status, version, created_at, updated_at, created_by, updated_by, deleted, deleted_at, deleted_by, delete_reason from expense_record
and project_id = #{projectId}
and budget_category_id = #{budgetCategoryId}
and status = #{status}
and expense_date >= #{startDate}
and expense_date <= #{endDate}
and (vendor like concat('%', #{keyword}, '%') or description like concat('%', #{keyword}, '%') or invoice_no like concat('%', #{keyword}, '%'))
order by expense_date desc, updated_at desc, id desc
